	@Test
	void authenticLegacyStoreKeepsItsPolicyAndAnOwnedAlternateAcrossReopen(@TempDir Path temporaryDirectory)
			throws Exception {
		LmdbCompatibilityFixtures.extract("canonical-iri-format-2.zip", temporaryDirectory);
		Path directory = temporaryDirectory.resolve("store");
		var manifest = CanonicalIriCompatibilityProcess.load(temporaryDirectory.resolve("manifest.properties"));
		byte[] originalPolicy = Files.readAllBytes(directory.resolve("store.properties"));
		LmdbLegacyV4TestFixture.install(directory);
		QuadSnapshotIdentity originalIdentity;
		Path alternate;

		SailRepository first = open(directory);
		try {
			CanonicalIriCompatibilityProcess.verify(first, manifest);
			LmdbStore store = (LmdbStore) first.getSail();
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			assertNotNull(estimator);
			assertTrue(estimator.forceFlush(), "the real statement source must complete a synopsis build");
			estimator.persistIfDirty();
			originalIdentity = estimator.quadSnapshotIdentity();
			assertEquals(CanonicalIriCompatibilityProcess.values().size(), predicateRows(estimator), 0.0d);
			try (var children = Files.list(directory)) {
				List<Path> alternates = children.filter(path -> path.getFileName().toString().startsWith(".rdf4j-estimator-"))
						.toList();
				assertEquals(1, alternates.size(), "the legacy regular file requires one owned alternate");
				alternate = alternates.getFirst();
			}
			assertTrue(Files.isRegularFile(alternate.resolve("owner")));
			assertTrue(Files.isRegularFile(alternate.resolve("synopsis/synopsis-v8.bin")));
			LmdbLegacyV4TestFixture.assertUnchanged(directory);
		} finally {
			first.shutDown();
		}

		SailRepository reopened = open(directory);
		try {
			CanonicalIriCompatibilityProcess.verify(reopened, manifest);
			LmdbStore store = (LmdbStore) reopened.getSail();
			assertTrue(store.awaitSketchesReady(20, TimeUnit.SECONDS));
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			assertEquals(originalIdentity.storeIdHigh(), estimator.quadSnapshotIdentity().storeIdHigh());
			assertEquals(originalIdentity.storeIdLow(), estimator.quadSnapshotIdentity().storeIdLow());
			assertEquals(CanonicalIriCompatibilityProcess.values().size(), predicateRows(estimator), 0.0d);
			assertTrue(Files.isRegularFile(alternate.resolve("owner")));
			LmdbLegacyV4TestFixture.assertUnchanged(directory);
		} finally {
			reopened.shutDown();
		}
		assertArrayEquals(originalPolicy, Files.readAllBytes(directory.resolve("store.properties")),
				"an estimator owner is not permission to rewrite an authentic format-2 policy");
	}


	@Test
	void olderWriterLeavesUnknownRegularAndOwnedAlternateFilesUntouchedButCurrentReopenIsSafe(
			@TempDir(cleanup = CleanupMode.NEVER) Path temporaryDirectory) throws Exception {
		String classpath = System.getProperty("rdf4j.lmdb.canonical.compat.classpath.format2");
		assumeTrue(classpath != null && !classpath.isBlank(), "Run with the authenticated RDF4J 6.1.0 process classpath");
		LmdbCompatibilityFixtures.extract("canonical-iri-format-2.zip", temporaryDirectory);
		Path directory = temporaryDirectory.resolve("store");
		var metadata = CanonicalIriCompatibilityProcess.load(temporaryDirectory.resolve("manifest.properties"));
		LmdbLegacyV4TestFixture.install(directory);
		Path legacyRegular = directory.resolve("join-estimator.rjes");
		Path legacySidecar = directory.resolve("join-estimator.rjes.sketches");
		byte[] originalRegular = Files.readAllBytes(legacyRegular);
		byte[] originalSidecar = Files.readAllBytes(legacySidecar);
		long transactionBeforeClose;
		QuadSnapshotIdentity originalIdentity;
		Path alternate;
		Path alternateOwner;
		Path alternateSnapshot;

		SailRepository first = open(directory);
		try {
			CanonicalIriCompatibilityProcess.verify(first, metadata);
			try (var connection = first.getConnection()) {
				connection.add(CanonicalIriCompatibilityProcess.CURRENT_SUBJECT,
						CanonicalIriCompatibilityProcess.PREDICATE, CanonicalIriCompatibilityProcess.CURRENT_IRI);
			}
			assertEquals(CanonicalIriCompatibilityProcess.values().size() + 1L, countPredicateRows(first));
			LmdbStore store = (LmdbStore) first.getSail();
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			assertNotNull(estimator);
			assertTrue(estimator.forceFlush(), "the current owner must complete a real synopsis build");
			assertTrue(estimator.persistIfDirty(), "the current owner must persist its owned alternate");
			originalIdentity = estimator.quadSnapshotIdentity();
			assertEquals(CanonicalIriCompatibilityProcess.values().size() + 1.0d,
					predicateRows(estimator), 0.0d, "the owned alternate starts from the real eleven-row source");
			try (var children = Files.list(directory)) {
				List<Path> alternates = children.filter(path -> path.getFileName().toString().startsWith(".rdf4j-estimator-"))
						.toList();
				assertEquals(1, alternates.size(), "the historical regular file is not replaced by the current owner");
				alternate = alternates.getFirst();
			}
			alternateOwner = alternate.resolve("owner");
			alternateSnapshot = alternate.resolve("synopsis/synopsis-v8.bin");
			assertTrue(Files.isRegularFile(alternateOwner));
			assertTrue(Files.isRegularFile(alternateSnapshot));
			LmdbLegacyV4TestFixture.assertUnchanged(directory);
			transactionBeforeClose = store.getBackingStore().getTripleStore().lastTransactionId();
		} finally {
			first.shutDown();
		}
		byte[] ownedReceipt = Files.readAllBytes(alternateOwner);
		byte[] ownedSnapshot = Files.readAllBytes(alternateSnapshot);

		Path output = temporaryDirectory.resolve("actual-release-writer.log");
		Process process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-ea", "-cp", classpath, CanonicalIriCompatibilityProcess.class.getName(),
				"verify-current-and-write", directory.toString(), temporaryDirectory.resolve("manifest.properties").toString())
				.redirectErrorStream(true).redirectOutput(output.toFile()).start();
		try {
			assertTrue(process.waitFor(60, TimeUnit.SECONDS), "The pinned release writer did not finish: " + output);
			assertEquals(0, process.exitValue(), () -> "The pinned release writer failed: " + output);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
			}
		}
		StoreProperties discovery = new StoreProperties(directory.toFile());
		assertTrue(discovery.load());
		LegacyStoreDiscovery.discover(directory.toFile(), discovery);
		assertTrue(discovery.verifiedTripleTransactionId > transactionBeforeClose,
				"the actual 6.1 writer must commit a later native data transaction");
		assertArrayEquals(originalRegular, Files.readAllBytes(legacyRegular),
				"the older writer leaves its authentic historical estimator file unchanged");
		assertArrayEquals(originalSidecar, Files.readAllBytes(legacySidecar),
				"the older writer leaves its authentic historical sketch sidecar unchanged");
		assertArrayEquals(ownedReceipt, Files.readAllBytes(alternateOwner),
				"the older writer cannot mutate the newer owner's alternate receipt");
		assertArrayEquals(ownedSnapshot, Files.readAllBytes(alternateSnapshot),
				"the older writer cannot mutate the newer owner's alternate synopsis");

		SailRepository reopened = open(directory);
		try {
			CanonicalIriCompatibilityProcess.verify(reopened, metadata);
			try (var connection = reopened.getConnection()) {
				assertTrue(connection.hasStatement(CanonicalIriCompatibilityProcess.CURRENT_SUBJECT,
						CanonicalIriCompatibilityProcess.PREDICATE, CanonicalIriCompatibilityProcess.CURRENT_IRI, false));
				assertTrue(connection.hasStatement(CanonicalIriCompatibilityProcess.OLD_SUBJECT,
						CanonicalIriCompatibilityProcess.PREDICATE, CanonicalIriCompatibilityProcess.OLD_IRI, false));
			}
			assertEquals(CanonicalIriCompatibilityProcess.values().size() + 2L, countPredicateRows(reopened),
					"the current owner must observe both the current and older writer's rows");
			LmdbStore store = (LmdbStore) reopened.getSail();
			boolean ready = store.awaitSketchesReady(20, TimeUnit.SECONDS);
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			assertEquals(originalIdentity.storeIdHigh(), estimator.quadSnapshotIdentity().storeIdHigh(),
					"the reopened estimator must retain the actual owner identity");
			assertEquals(originalIdentity.storeIdLow(), estimator.quadSnapshotIdentity().storeIdLow(),
					"the reopened estimator must retain the actual owner identity");
			QuadEvidence evidence = predicateEvidence(estimator);
			boolean exactCurrent = ready && evidence.usable()
					&& Double.compare(CanonicalIriCompatibilityProcess.values().size() + 2.0d,
							evidence.rows().estimate()) == 0;
			boolean typedUnavailable = !ready && !evidence.usable()
					&& evidence.rows().confidence() == 0.0d
					&& "unavailable".equals(evidence.rows().source())
					&& evidence.rows().snapshotIdentity().equals(estimator.quadSnapshotIdentity());
			assertTrue(exactCurrent || typedUnavailable,
					"current reopen must be ready with exact 12-row evidence or report typed unavailability "
							+ "when not ready; stale usable evidence is forbidden: ready=" + ready + ", evidence=" + evidence);
			assertArrayEquals(ownedReceipt, Files.readAllBytes(alternateOwner),
					"current reopen must preserve the stable alternate owner receipt");
			LmdbLegacyV4TestFixture.assertUnchanged(directory);
		} finally {
			reopened.shutDown();
		}
	}

	private static double predicateRows(SketchBasedJoinEstimator estimator) {
		return predicateEvidence(estimator).rows().estimate();
	}

	private static QuadEvidence predicateEvidence(SketchBasedJoinEstimator estimator) {
		return estimator.synopsisService().probe(new QuadProbe(QuadProbe.PREDICATE, QuadProbe.SUBJECT, 0L,
				QuadValueHash.hash(CanonicalIriCompatibilityProcess.PREDICATE), 0L, 0L,
				estimator.quadSnapshotIdentity()));
	}

	private static long countPredicateRows(SailRepository repository) {
		long count = 0L;
		try (var connection = repository.getConnection();
				var statements = connection.getStatements(null, CanonicalIriCompatibilityProcess.PREDICATE, null, false)) {
			while (statements.hasNext()) {
				statements.next();
				count++;
			}
		}
		return count;
	}

	private static SailRepository open(Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setTripleTermIndexes("spoc,cspo")
				.setInlineLiterals(false).setAutoGrow(true).setValueDBSize(16L * 1024 * 1024)
				.setTripleDBSize(16L * 1024 * 1024).setSketchEstimatorEnabled(true)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
		config.setExperimentalQueryOptimizations(true);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 20, TimeUnit.SECONDS);
			return repository;
		} catch (Throwable failure) {
			try { repository.shutDown(); } catch (Throwable cleanup) { if (cleanup != failure) { failure.addSuppressed(cleanup); } }
			throw failure;
		}
	}
